// Worker entry: the OpenNext app (fetch) + the daily cron (scheduled), the "custom worker"
// pattern from the OpenNext docs. wrangler.jsonc points "main" here.
// At 07:00 UTC (08:00 Algeria) the cron sends POST /api/cron/daily with the CRON_SECRET header
// straight into the app's own fetch handler: same code path as the admin "Run daily job now".

// @ts-ignore -- generated by `opennextjs-cloudflare build`, does not exist before the build
import handler from "./.open-next/worker.js";

// Durable Objects the OpenNext build may define (re-exported unchanged)
// @ts-ignore -- generated file
export * from "./.open-next/worker.js";

type Env = CloudflareEnv & { CRON_SECRET?: string };

export default {
  fetch: handler.fetch,

  async scheduled(_controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    const req = new Request("https://cron.internal/api/cron/daily", {
      method: "POST",
      headers: { "x-cron-secret": env.CRON_SECRET ?? "" },
    });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (res: Response) => {
        if (!res.ok) console.error("daily job failed", res.status, await res.text());
      }),
    );
  },
} satisfies ExportedHandler<Env>;
